      bool lo=(B[i]==mn && B[i]<=B[i-1] && B[i]<=B[i+1]);
      if(!(hi||lo)) continue;
      double d=MathMin(MathAbs(B[i]-B[i-1]),MathAbs(B[i]-B[i+1]));
      if(d<0.55*th) continue;

