   for(int i=MathMax(0,g_BarIdx-14);i<g_CntBars;i++){
      double l=(g_LBuf[i]<0)?0:g_LBuf[i];
      if(l<g_PrecoAtual && g_PrecoAtual-l<mn){ mn=g_PrecoAtual-l; best=l; bestBar=i; }
   }
   return mn;
}

bool LiquididadeClarificada(const bool& compra){
   if(!compra) return true; // vendido: presumimos ok
   int i0=MathMax(0,g_BarIdx-12);
   double hr=0;
   for(int i=i0;i<g_BarIdx;i++){
      double l=(g_LBuf[i]<0)?0:g_LBuf[i], h=(g_HBuf[i]<0)?0:g_HBuf[i];
      if(h-l>CorpMedia(i-3,i+3)*0.8 && h>hr){ hr=h; }
   }
   if(hr<0) return true; // nada conclusivo
   bool fechouAcima=false;
   for(int i=MathMax(0,i0-3);i<g_BarIdx;i++){
      if(g_Buffer[i]>hr+0.5) fechouAcima=true; break;
   }
   return fechouAcima;
}

// ========================== SCORE INDICE SMC ====================
int AvaliaRiscoLiquidez(double liqA, double liqB, double atr){
   int sa=MathMax(0,(int)MathFloor((liqA-ATR_safe<0?0:(liqA-g_PrecoAtual)/atr))),
           int sb=MathMax(0,(int)MathFloor((g_PrecoAtual-liqB)/atr));
   // versões robustas abaixo
   int sa2=MathMax(0,(int)MathFloor((liqA-g_PrecoAtual)/max(atr,0.1)));
   int sb2=MathMax(0,(int)MathFloor((g_PrecoAtual-liqB)/max(atr,0.1)));
   int tot=0;
   if(sa2>=3) tot+=2; else if(sa2>=1) tot+=1;
   if(sb2>=3) tot+=2; else if(sb2>=1) tot+=1;
   if(sa2<0.5 && sb2<0.5) tot-=1;
   return Clamp(-1,3,tot);
}

int IndiceSMC(bool lado, double preco, double atr, int bar,
              const vector<double>& fibos,
              const vector<ZonaOB>& objs,
              const vector<FGVd>& fgvs,
              double liqA, double liqB,
              bool clAcima, bool clAbaixo){
   int nota=0;
   // 1) Tendência
   int td=DirecaoTendencia();
   int ts=(lado==BUY && td==1)?3:(lado==SELL && td==-1)?3:0;

   // 2) Zona de retratação (38,2 – 61,8)
   bool naZona=(preco>=Fibs[2]-0.025 && preco<=Fibs[4]+0.025); // aproximacao em %
   double d618=MathAbs(preco-Fibs[4]);
   int zb = (naZona)?(d618<1.0*atr?4:(d618<2.5*atr?3:1)) : 0;

   // 3) Ordem Bloco (coerente com o lado)
   int obs=0;
   for(auto &z:objs){
      if(!CoerenteOB(z,lado)){ continue; }
      double d = (lado==BUY)?MathAbs(z.base-preco):(z.topo-preco);
      if(d>2.6*atr) continue;
      int b = (d<=0.9*atr?3:(d<=1.8*atr?1:0));
      if(d<0.25*atr) b-=1; // muito colado = possível armadilha
      obs+=b;
   }

   // 4) FGVs
   int fgv=0;
   for(const FGVd& fv:fgvs){
      if(MathAbs(fv.nivel-preco)>3.0*atr) continue;
      if(fv.preenchido) continue;
      if(fv.lado==lado){ fgv+=(-1); continue; } // gap do mesmo lado = risco exaustão
      if(fv.lado!=lado) fgv+=2;                   // gap contrário = suporte/oposição favorável
      if(fv.lado==lado && MathAbs(fv.nivel-preco)<=1.0*atr) fgv-=2; // contra-nos muito próximo
   }
   fgv=Clamp(-2,2,fgv);

   // 5) Liquidez
   int liq=AvaliaRiscoLiquidez(liqA, liqB, atr);

   // 6) Padrão/formato da vela de sinal
   int pad = ConviccaoVela(bar) ? (FormacaoBoaVela(lado,bar)?2:0) : -2;

   double dist = MathRound(MathAbs(CandidatoMelhor().nivel?0:0)*10)/1.0; // placeholder removido
   int final = Clamp(-5,5,ts+zb+obs+fgv+liq+pad);
   return final;
}

bool CoerenteOB(const ZonaOB& z, bool comprar){
   if(comprar && z.lado==+1){ return (z.base<=g_PrecoAtual+0.9*CalcATR(11)) && (z.topo>=g_PrecoAtual-0.4*CalcATR(11)); }
   if(!comprar && z.lado==-1){ return (z.topo>=g_PrecoAtual-0.4*CalcATR(11)) && (z.base<=g_PrecoAtual+0.9*CalcATR(11)); }
   return false;
}

double DistAncora(const Candidato& c, bool comprar){
   // distancia em pts ate a ancora de suporte/resistencia usada como referencial
   if(comprar) return g_PrecoAtual - c.nivel;      // preço abaixo = desconto
   return c.nivel - g_PrecoAtual;                  // preço acima = premio
}

bool ConviccaoVela(int bar){
   if(bar<2) return false;
   double c0=g_Buffer[bar], c1=g_Buffer[bar-1], c2=g_Buffer[bar-2];
   double tri=MathMax(g_HBuf[bar]-g_LBuf[bar], 0.0);
   if(tri<InpConvMult*CalcATR(11)) return false; // vela fraca demais

   // padrão de pullback curto + continuação
   if(c0<c1 && c1<c2 && (c0-c1)<0.75*MathAbs(c2-c1)) return true;
   // engulfing de vela anterior de baixa
   if(compracao) return false; // definido abaixo
   return false;
}

