      bool compra = (oi<4 && !InpExtenders) || (oi>=5); // 0-3=0,23,38,50; 4=61,8; 5+ = extensores
      if(!compra && lvl<g_PrecoAtual) continue;  // extensor acima do preco sempre valida
      if(compra && lvl>g_PrecoAtual+InpLiqSafe) continue; // nao comprar demasiado acima do preco

      int tipo = oi==0?0: oi==1?1: oi==2?2: oi==3?3: (oi==4?4: (oi<9?5:(int)(oi-5))));
      // pesos internos: quanto mais perto do 61,8% maior o peso natural
      int peso = (oi==4?30:(oi==3?18:(oi==2?10:1)));
