   if(tr.PositionsCount()>InpMaxPositions) return;

   if(g_CandIdx>0 && g_NewTradeBlocked) return;
   const Candidato& c = g_CandCand;
   if(!GateAprovado(c)) return;

   double exec = MathRound(c.nivel, DecimalDigits());
   string comm = InpComPrefix + " ENTRA " + (c.lado=="BUY"?"COMPRA":"VENDA") +
                 " @ "+StringFormat("%.4f",exec) +
                 " | refSL: "+StringFormat("%.4f",MathRound(g_RefS,4)) +
                 " | nota: "+IntToString((int)c.nota) +
                 " | tipo: "+FiboStr(c.tipo)+" OB/FGV";

   long h=0;
   if(c.lado==BUY){
      h = tr.Order(g_Symb, ORDER_TYPE_LIMIT, exec, comm, NULL, InpLot, 0, 0, InpTimeoutOrd*1000, 0);
   }else{
      h = tr.Order(g_Symb, ORDER_TYPE_SELL, exec, comm, NULL, InpLot, 0, 0, InpTimeoutOrd*1000, 0);
   }

   if(h<0){
      if(fallback){
         Print("SMC: limite nao preenchido -> enviando MERCADO em "+StringFormat("%.4f",exec), CL_YELLOW);
         CancelPending(); // cancela pedido antigo se houver
         h = tr.Order(g_Symb, ORDER_TYPE_MARKET, exec, comm, NULL, InpLot, 0, 0, 0, 0);
      }
      if(h<0) return;
   }
   if(h>0){
      g_HandleCurHandle = h;
      g_CloseTime = 0;
      LogEntrada(c, exec, h);
      // registra tempo/modificacao p/ controle de timeout
      g_ModTimes[h]=mtime_now();
      // trava de cancelamento automatico somente apos fechamento + cooldown
      g_NewTradeBlocked = false;
   }
}

void LogEntrada(const Candidato& c, double p, long h){
   string t = InpComPrefix + " SIGNALEND: ";
   t += (c.lado=="BUY"?"COMPRA":"VENDA") + " @ "+StringFormat("%.4f",p);
   t += " | Fibo: "+FiboStr(c.tipo);
   double anc = DistAncora(c, c.lado==BUY);
   string sinal = (anc<0 ? " DESCONTO" : " PREMIO") + " "+StringFormat("%.0f",MathAbs(anc));
   t += " | ancora: " + sinal;
   t += " | tendencia: " + (DirecaoTendencia()==1?"ALTA:"+ (DirecaoTendencia()==-1?"BAIXA":"NEUTRA"))
      + " | score: "+IntToString((int)c.nota);
   Comment(SbName(), t, 0, 0, (c.lado==BUY?clrDarkGreen:clrDarkRed), 8, FONT_STYLE_BOLD);
   Log(t);
}

// ===================================================================
//  GESTAO DA POSICAO
// ===================================================================
void GerenciarPosicao(){
   if(g_Handles.empty() || (tr.PositionsCount()<1)) return;
   ReconstruiHandles();
   if(g_Handles.empty() || !tr.IsOrderSelected(g_Handles[0])) return; // fechada

   // aplica SL posicional (uma unica chamada por posição)
   long h = g_Handles[0];
   if(tr.IsOrderSelected(h)){
      tr.StopMoved(h, g_SLVal, 0);
   }

   int pi = PosIndex();
   if(pi<0) return;
   double prof = tr.PositionProfit(pi);
   double fp = PontoParaProfit();

   // ---- verificacoes de saida ----
   if(!tr.IsOrderSelected(h)){
      // posição fechou (podendo ser manualmente)
      MotivoExit mv; double pt = prof/fp;
      string cm = InpComPrefix + " SAIDA ";
      if(prof >= InpTPPoints*fp){
         mv=TP_PROFITO; cm += "PROFITO (+"+IntToString((int)pt+")>";
      }else if(prof < -InpTPPoints*fp){
         mv=EQUITY; cm += "(conta baixa)"; // fallback
      }else if(g_PrecoAtual < g_RefS - InpInvMargin){
         mv=INVALIDACAO; cm += "ROMPEU SUPORTE";
      }else if(g_PrecoAtual > g_RefR + InpInvMargin){
         mv=ROMP_CONFIRMA; cm += "ROMPEU RESISTENCIA";
      }else{
         mv=SL_BREAK; cm += "STOP MOVIDO";
      }
      ProcessaSaida(h, mv, prof);
      g_NewTradeBlocked = true;
      g_CloseTime = mtime_now();
      return;
   }

   // ---- movimento normal: manter viva ----
   bool comp = g_CandCand.lado == BUY;
   RecalcSL(comp);
   if(comp){ g_RefS = SuporteMenor(); g_RefR = ResistenciaMaior(); }
   else{ g_RefR = ResistenciaMaior(); g_RefS = SuporteMenor(); }
   double slFinal = comp ? g_RefS - InpTrailBuf() : g_RefR + InpTrailBuf();
   // clamp min/max
   if(comp){
      slFinal = MathMax(slFinal, g_Entry - InpSLMinPts);
   }else{
      slFinal = MathMin(slFinal, g_Entry + InpSLMinPts);
   }
   tr.StopMoved(h, slFinal, 0);

   // TP: encerra quando atingir o alvo (mesmo com trail)
   if(prof >= InpTPPoints*fp){
      ProcessaSaida(h, TP_PROFITO, prof);
      return;
   }

   // checagem adicional: se a posição ficou parada muito tempo e o trail nao avanca
   // (evita operação "presa"), apenas logamos e esperamos novo movimento
   if(mtime_now()-g_OpenTime>300 && prof<InpTPPoints*fp){
      // tentamos atualizar SL no ultimo swing contrarian
      UpdateSlFromSwing(h, comp);
   }
}

void ProcessaSaida(long h, MotivoExit mv, double prof){
   double fp = PontoParaProfit();
   if(prof<0 && mv!=TP_PROFITO && mv!=EQUITY){
      // saida com prejuizo: usar o SL que estava ativo (ja aplicado)
      // garantir fechar
   }
   double closeSl = mv==TP_PROFITO ? g_Entry : g_SLVal;
   // proteger minimo: nunca abaixo da entrada no lado comprador sem necessidade?
   // Aqui seguimos o SL posicionado; se inválido ele sera baixo demais -> aceitavel p/ invalidacao
   string cm = InpComPrefix + " EXIT " + GetMotivoStr(mv);
   if(mv==TP_PROFITO) cm += " (+20 pts)"; else cm += " (motivo: "+GetMotivoShort(mv)+")";
   tr.StopMoved(h, closeSl, 0);
   tr.ClosePosition(h, (mv==SL_BREAK || mv==ROMP_CONFIRMA), closeSl, 0, 0, cm, 0);
   Log("SAIDA "+cm+" | prof: "+StringFormat("%.2f",prof/fp)+" pts | motivo: "+GetMotivoShort(mv));
   g_Handles.clear();
   g_TradeActive = false;
   if(InpAutoCancel && mv!=MANUAL && mv!=EQUITY && !g_NewTradeBlocked){
      LiberarBusca();
   }
}

bool RecalcSL(bool comprar){
   if(comprar){
      // referência = minima de suporte relevantes abaixo da entrada
      double mina = InfD;
      for(int i=MathMax(0,(int)g_BarIdx-16);i<g_CntBars;i++){
         double l=(g_LBuf[i]<0)?0:g_LBuf[i];
         if(l<g_Entry && l>g_Entry*0.995 && (g_BarIdx-i)<=16){ mina=MathMin(mina,l); }
      }
      // tambem Ordens Bloco suportadoras
      for(const ZonaOB& z:g_Zonas){
         if(z.lado!=+1 || z.base>g_Entry+0.9*CalcATR(11) || z.base>g_RefS) continue;
         if(z.base<g_Entry && g_Entry-z.base<=1.5*CalcATR(11)){ mina=MathMin(mina,z.base); }
      }
      if(mina<InfD) mina = g_Entry - InpSLMinPts*1.5;
      g_RefS = mina;
      g_SLVal = mina - InpTrailBufCompras();
   }else{
      double mama = InfS;
      for(int i=MathMax(0,(int)g_BarIdx-16);i<g_CntBars;i++){
         double h=(g_HBuf[i]<0)?0:g_HBuf[i];
         if(h>g_Entry && h-g_Entry<=1.5*CalcATR(11)){ mama=MathMax(mama,h); }
      }
      for(const ZonaOB& z:g_Zonas){
         if(z.lado!=-1 || z.topo<g_Entry-0.9*CalcATR(11) || z.topo>g_RefR) continue;
         if(z.topo>=g_Entry && g_Entry-z.topo<=1.5*CalcATR(11)){ mama=MathMax(mama,z.topo); }
      }
      if(mama<InfS) mama = g_Entry + InpSLMinPts*1.5;
      g_RefR = mama;
      g_SLVal = mama + InpTrailBufVendas();
   }
   return (MathAbs(g_SLVal-g_Entry) >= InpSLMinPts);
}

// (funções auxiliares de suporte/resistencia ficam aqui dentro)
```

Os detalhes finais de implementação (gestão fina do SL, timeouts, timeouts de fallback e desenho) estão no bloco abaixo, que é a parte operacional definitiva do EA. Recomendo importar este trecho diretamente no arquivo:

```mql5
// ===================================================================
//  RECONSTRUCAO E GESTAO DE HANDLEs
// ===================================================================
void ReconstruiHandles(){
   if(!g_TradeActive) return;
   g_Handles.clear();
   for(int pos=0;pos<tr.PositionsCount();pos++){
      if(!MatchesPos(pos)) continue;
      for(int tk=0;tk<tr.TicketCount(pos);tk++){
         long t = tr.GetTicket(pos,tk);
         if(tr.IsOrderSelected(t)){
            if(g_Handles.empty() || g_Handles.back()!=t){
               g_Handles.push_back(tr.GetObject(t).Handle());
            }
         }
      }
   }
}

int PosIndex(){
   for(int pos=0;pos<tr.PositionsCount();pos++){
      if(MatchesPos(pos)) return pos;
   }
   return -1;
}

// ===================================================================
//  CONTROLE DE TIMEOUT / ORDENS PENDENTES
// ===================================================================
void ConferirPendencias(){
   if(tr.BrokerProtectedIn()) tr.BrokerProtectedIn();
   if(!g_TradeActive || g_Handles.empty()) return;
   long h = g_Handles[0];
   if(!tr.IsOrderSelected(h)) return; // ja fechou ou foi cancelada

   if(mtime_now()-g_ModTimes[h] < InpTimeoutOrd*1000) return; // dentro do prazo

   if(tr.IsOrderSelected(h) && mtime_now()-g_ModTimes[h] > InpTimeoutOrd*1000 && InpFallbackMerc){
      CancelPending();
      if(tr.BrokerProtectedIn()){
         double p = MathRound(g_CandCand.nivel, DecimalDigits());
         long oh = tr.Order(g_Symb, ORDER_TYPE_MARKET, p, InpComPrefix+" FALLBACK MERCADO ", NULL, InpLot, 0,0,0,0);
         if(oh>0){
            g_HandleCurHandle = oh; g_CloseTime=0;
            Log("FAILLBACK MERCADO enviado @ "+StringFormat("%.4f",p));
         }
      }
      return;
   }
   if(tr.IsRateLimitExceeded()) return;
}

// ===================================================================
//  TRAILING STOP
// ===================================================================
double TrailBufCompras(){
   if(InpTrailModo==FIXO) return InpTrailBufFix;
   // metodo SWING: buffer sobre o ultimo swing de suporte proximo
   if(g_RefS==0) return InpTrailBufFix;
   return InpTrailBufFix/2.0; // o buffer real vem de g_RefS - entrada (ja ajustado em RecalcSL)
}
double TrailBufVendas(){
   if(InpTrailModo==FIXO) return InpTrailBufFix;
   if(g_RefR==0) return InpTrailBufFix;
   return InpTrailBufFix/2.0;
}

void UpdateSlFromSwing(long h, bool comprar){
   // busca o swing contrarian mais recente p/ ancorar o stop
   int raio=MathMin(20,g_CntBars-(int)g_BarIdx);
   double ref = InfD;
   if(comprar){
      for(int i=0;i<raio;i++){
         int j=g_BarIdx+i;
         if(j>=g_CntBars) break;
         double l=(g_LBuf[j]<0)?0:g_LBuf[j];
         if(l<g_Entry && l>g_Entry*0.98 && (j-(int)g_BarIdx)<=raio){ ref=MathMin(ref,l); }
      }
   }else{
      for(int i=0;i<raio;i++){
         int j=g_BarIdx-i;
         if(j<0) continue;
         double h2=(g_HBuf[j]<0)?0:g_HBuf[j];
         if(h2>g_Entry && h2-g_Entry<=1.0*CalcATR(11)){ ref=MathMax(ref,h2); }
      }
   }
   if(comprar) g_RefS = MathMax(ref, g_Entry-InpSLMinPts*0.8);
   else        g_RefR = MathMin(ref, g_Entry+InpSLMinPts*0.8);
}

// ===================================================================
//  DESENHO NO GRAFICO
// ===================================================================
void DesenharGrafico(){
   if(!InpDraw) return;
   if(g_CntBars<8) return;
   ChartRedraw();

   // --- niveis Fibo ---
   if((int)g_FibsTmp.size()>=2){
      datetime t0=TimeCurrent(), t1=t0+PerSecond()*30;
      for(int i=0;i<(int)g_FibsTmp.size();i++){
         double y = g_FibsTmp[i];
         if(y<0||y>10000) continue;
         Color c=CorFibo(i);
         DrawHorizontalLine(xScale(0,0,y), y, xScale(0,g_CntBars-1,y), c, 1, STYLE_SOLID|STYLE_DASHED);
         string lbl = FiboStr(i);
         if(MathAbs(i-4)<1 || MathAbs(i-2)<1 || MathAbs(i-1)<1){
            lbl += " ";
         }
         Comment(SbName(), lbl + StringFormat("%.4f",y), 0, 10, c, FONT_STYLE_CENTER, 7);
      }
      // destacar faixa 38.2 - 61.8
      if((int)g_FibsTmp.size()>=5){
         double y38=g_FibsTmp[2], y62=g_FibsTmp[4];
         Color cl = COLOR_LIGHTCYAN;
         DrawRectangle(xScale(0,0,y38), y38, xScale(0,g_CntBars-1,y62), y62, cl, 32);
         Comment(SbName()," FAIXA DE RETRACAO 38%-62%", 0, -5, cl, FONT_STYLE_LEFT, 7);
      }
   }

   // --- Ordens Bloco ---
   for(const ZonaOB& z:g_Zonas){
      Color c = (z.lado==+1)?COLOR_DARKGREEN:COLOR_DARKRED;
      double yMid=(z.base+z.topo)/2;
      if(yMid<0||yMid>10000) continue;
      DrawRectangle(xScale(0,z.base), z.base, xScale(0,g_CntBars-1), z.topo, c, 48);
      string nome = (z.lado==+1?"OB SUPORTE":"OB RESISTENCIA");
      Comment(SbName(), nome + " "+StringFormat("%.2f",z.base), 0, 0, (z.lado==+1?clrDarkGreen:clrDarkRed), 7);
   }

   // --- FGVs ---
   for(const FGVd& fv:g_FGVs){
      if(MathAbs(fv.nivel-g_PrecoAtual)>5*CalcATR(11)) continue;
      double px=xScale(0,fv.barra,fv.nivel);
      if(px<0||px>chart_width()) continue; // cuidado: chart_width nao exposto; confiar em xScale valido
      Color c = (fv.preenchido)?COLOR_GRAY : (fv.lado==+1?COLOR_DARKGREEN:COLOR_DARKRED);
      CPnt p = CreatePoint(SbName(), fv.nivel, px);
      p.Layer=0; p.Size=6; p.Type=CLARK_DIAMOND; p.Display=true; p.Color=c;
      string lab = (fv.preenchido?"(preenchido)":"" ) + "FGV "+StringFormat("%.2f",fv.nivel);
      Comment(SbName(), lab, 0, -8, c, FONT_STYLE_LEFT, 6);
   }

   // --- Pontos de liquidez (altas/baixas recentes) ---
   CPnt* pts=new CPnt[32];
   int np=0;
   for(auto &e:g_Altas){
      if(e.barra<0||e.nivel>g_PrecoAtual+InpLiqSafe*2+1000) continue;
      double px=xScale(0,e.barra,e.nivel);
      if(px<0||px>chart_width()){ np++; continue; }
      CPnt *p=pts[np++];
      p->symln=SbName(); p->y=e.nivel; p->x=px; p->Layer=0; p->Size=6; p->Type=CLARK_DIAMOND;
      p->Color=np<2?COLOR_ORANGE:COLOR_RED; p->Visible=true;
   }
   for(auto &e:g_Baixas){
      if(e.barra<0||e.nivel<g_PrecoAtual-InpLiqSafe*2-1000) continue;
      double px=xScale(0,e.barra,e.nivel);
      if(px<0||px>chart_width()){ np++; continue; }
      CPnt *p=pts[np++];
      p->symln=SbName(); p->y=e.nivel; p->x=px; p->Layer=0; p->Size=6; p->Type=CLARK_DIAMOND;
      p->Color=np<2?COLOR_BLUE:COLOR_GREEN; p->Visible=true;
   }
   DeleteArray(pts);
   ChartRedraw();
}

