bool MatchesPos(int pos){
   string sy = TrimmSyml(tr.Symbol(pos));
   return sy==g_Symb && tr.Magic(pos)==InpMagic;
}

void Log(string txt, CL_COLOR c=CL_GREEN){ Print(txt, c); }
void LogErro(string txt){ Print("[ERRO] "+txt, CL_RED); }
string GetMotivoStr(MotivoExit m){
   switch(m){ caseTP_PROFITO:"alvo +20pts"; caseSL_BREAK:"stop atingido";
              caseINVALIDACAO:"rompeu suporte"; caseROMP_CONFIRMA:"rompeu resistencia";
              caseEQUITY:"conta baixa"; caseMANUAL:"manual"; default:"desconhecido";}
   return string();
}
string GetMotivoShort(MotivoExit m){
   switch(m){ caseTP_PROFITO:"+20"; caseSL_BREAK:"SL"; caseINVALIDACAO:"INV";
              caseROMP_CONFIRMA:"ROM"; caseEQUITY:"EQ"; default:"?";}
   return string();
}

double SuporteMenor(){
   double mn=InfD;
   for(const ZonaOB& z:g_Zonas){
      if(z.lado!=+1) continue;
      if(z.base<g_Entry && z.base>g_Entry*0.995){ mn=MathMin(mn,z.base); }
   }
   // tambem minima de baixas recentes
   for(int i=MathMax(0,(int)g_BarIdx-16);i<g_CntBars;i++){
      double l=(g_LBuf[i]<0)?0:g_LBuf[i];
      if(l<g_Entry && l>g_Entry*0.995 && (g_BarIdx-i)<=14){ mn=MathMin(mn,l); }
   }
   return mn;
}
double ResistenciaMaior(){
   double mx=InfS;
   for(const ZonaOB& z:g_Zonas){
      if(z.lado!=-1) continue;
      if(z.topo>=g_Entry && z.topo<g_Entry+1.5*CalcATR(11)){ mx=MathMax(mx,z.topo); }
   }
   for(int i=MathMax(0,(int)g_BarIdx-16);i<g_CntBars;i++){
      double h=(g_HBuf[i]<0)?0:g_HBuf[i];
      if(h>g_Entry && h-g_Entry<=1.5*CalcATR(11)){ mx=MathMax(mx,h); }
   }
   return mx;
}
double InfD(){ return 1e30; }
double InfS(){ return -1e30; }

double PontoParaProfit(){
   double pt = SymbolInfoDouble(g_Symb, SYMBOL_POINT);
   return InpLot * pt * 100.0 / 100.0; // pontos -> lucro (ajuste fino: dividir por 10 se SYMBOL_ADR...)
}
