Candidato g_CandCand;
int       g_CandCacheAge=0;

// ===================================================================
//  MAIN: ONINIT
// ===================================================================
void OnInit(){
   if(ExpertSlave!=true){ Print("SMC: configure o Expert como Escravo!", CL_RED); return; }
   if(!AccountIsValid()) return;

   g_Symb = TrimmSyml(AccountInfoString(ACCOUNT_SYMBOL));
   g_ChartID = ChartIndex();
   if(g_ChartID<0) return;
   ChartSetTitle(g_ChartID, g_Symb + " | SMC 61.8% Pullback Auto", 0);

   tr.LoadSymbol(g_Symb);
   tr.SetMagicNumber(InpMagic);

   // inicializacao de buffers
   ArrayResize(g_Buffer, MAXBUF); ArrayFill(g_Buffer, 0, MAXBUF, 0);
   ArrayResize(g_HBuf, MAXBUF); ArrayFill(g_HBuf, 0, MAXBUF, 0);
   ArrayResize(g_LBuf, MAXBUF); ArrayFill(g_LBuf, 0, MAXBUF, 0);
   ArrayResize(g_Ema9, MAXBUF); ArrayFill(g_Ema9, 0, MAXBUF, 0);
   ArrayResize(g_Ema21, MAXBUF); ArrayFill(g_Ema21, 0, MAXBUF, 0);
   g_Altas.clear(); g_Baixas.clear(); g_Zonas.clear(); g_FGVs.clear(); g_Handles.clear();
   g_CandCand={}; g_CandIdx=-1; g_NewTradeBlocked=true;

   int bp = (PerSecond()/InpBarPeriod);
   if(bp<=0) bp=1;
   g_ProxBar = (IntTimeframe(InpBarPeriod)) + bp;

   AnaliseInicial();
   Print("SMC iniciado | periodo:", IntTimeframe(InpBarPeriod), "s | bar aprox:", bp,
         " | Fibo range OK:", (g_FibsTmp.size()>=2 ? "SIM" : "Nao (verifique)"));
}

// ===================================================================
//  MAIN: ONTTICK
// ===================================================================
void OnTick(){
   ConferirFrame();
   if(!AccountIsValid()) return;

   CopiarDados();
   if(g_CntBars<8) return;

   ConferirPendencias();
   AnaliseInicial();
   // gere cache de candidato (só recalcula pesado a cada X ciclos)
   if(g_CandCacheAge==0){
      GerarCandidatos();
      g_CandCand = EscolherCandidato();
      g_CandCacheAge = InpLookBack/20; // reavalida cache a cada ~20 barras
   }else if(g_CandCacheAge>0 && g_CandCacheAge--<InpLookBack/40){
      // forca reavaliacao ocasional
      GerarCandidatos();
      g_CandCand = EscolherCandidato();
   }

   if(g_CandCand.nota>=InpScoreMin && !g_NewTradeBlocked && !g_TradeActive && !InpAutoCancel){
      EnviarPedido(false);
      g_NewTradeBlocked = false;
      g_CloseTime = 0;
   }

   ConferirTimeouts();
   GerenciarPosicao();
   DesenharGrafico();
}

void ConferirTimeouts(){
   if(tr.BrokerProtectedIn()) tr.BrokerProtectedIn();
   if(!g_TradeActive || g_Handles.empty()) return;
   long h = g_Handles[0];
   if(!tr.IsOrderSelected(h) || mtime_now()-g_ModTimes[h]<InpTimeoutOrd*1000) return;
   // ordem ainda pendente e dentro do prazo -> nada a fazer
}

